import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    results = []
    while True:
        try:
            n = int(next(it))
            target = int(next(it))
        except StopIteration:
            break

        arr = []
        for _ in range(n):
            try:
                arr.append(int(next(it)))
            except StopIteration:
                break

        reachable = {0}
        for x in arr:
            # create new sums without altering the set during iteration
            new_sums = {s + x for s in reachable}
            reachable |= new_sums
            if target in reachable:
                # early exit possible, but continue to consume remaining numbers already read
                pass
        results.append("Yes" if target in reachable else "No")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
